        // --- LOGIC FUNCTIONS ---

        function loadBlackbox() {
            const saved = localStorage.getItem(STORAGE_KEY);
            if (saved) {
                try {
                    const parsed = JSON.parse(saved);
                    blackbox = { ...blackbox, ...parsed };
                    if (blackbox.cases && blackbox.cases.length > 0) {
                        cases = blackbox.cases;
                        renderCases();
                    }
                    if (blackbox.whaleHits && blackbox.whaleHits.length > 0) {
                        const list = document.getElementById('report-list');
                        if (list.innerText.includes("WAITING")) list.innerHTML = "";
                        blackbox.whaleHits.forEach(tx => renderReportRow(tx));
                    }
                } catch(e) { console.error("Blackbox corrupted. Resetting."); }
            } else {
                blackbox.genesis = new Date().toISOString();
            }
            const today = new Date().toISOString().split('T')[0];
            if (!blackbox.dailySnapshots[today]) {
                blackbox.dailySnapshots[today] = { xrp: 0, usd: 0, tx: 0 };
            }
            // Seed the report with ~1y of REAL volume so a fresh install isn't all-zero.
            _ensureHistory();
            try { backfillHistory(); } catch (e) { console.error('backfill init', e); }
            setInterval(saveBlackbox, 5000);
        }

        function saveBlackbox() {
            blackbox.lastActive = new Date().toISOString();
            blackbox.cases = cases;
            localStorage.setItem(STORAGE_KEY, JSON.stringify(blackbox));
        }

        // ── HISTORICAL VOLUME BACKFILL (v16.8) ──────────────────────
        // A fresh install has no observed data, so every report reads 0.
        // We seed ~1y of REAL volume. Two sources, kept SEPARATE + labeled:
        //   • EXCHANGE  – Binance.US daily klines (market trading volume)
        //   • ON-CHAIN  – whale flow this scanner has observed live
        //                 (no free historical ledger-volume feed exists)
        const BACKFILL_SYMBOLS = ['XRPUSDT', 'XRPUSD'];
        const BACKFILL_DAYS = 366;
        let _backfillRunning = false;

        function _ensureHistory() {
            if (!blackbox.history) {
                blackbox.history = {
                    exch:  { xrp:0, usd:0, tx:0, days:0, updated:null, source:'Binance.US 1d', status:'pending' },
                    chain: { xrp:0, tx:0, wallets:0, spanDays:0, updated:null, source:'XRPL account_tx (main wallets)', status:'pending' },
                    daily: {}
                };
            }
            return blackbox.history;
        }

        function _xrpShort(n){ n=Number(n)||0; if(n>=1e9) return (n/1e9).toFixed(2)+'B'; if(n>=1e6) return (n/1e6).toFixed(2)+'M'; if(n>=1e3) return (n/1e3).toFixed(1)+'K'; return Math.floor(n).toLocaleString(); }

        async function backfillHistory(force) {
            const h = _ensureHistory();
            const todayKey = new Date().toISOString().split('T')[0];
            // Refresh at most once per UTC day unless forced.
            if (!force && h.exch.updated && h.exch.updated.split('T')[0] === todayKey && h.exch.status === 'ok') {
                scanChainVolume(); renderHistoryBanner(); return;
            }
            if (_backfillRunning) return;
            _backfillRunning = true;
            _setBackfillLoading(true);
            try {
                let klines = null, used = null;
                for (const sym of BACKFILL_SYMBOLS) {
                    try {
                        const r = await fetch('https://api.binance.us/api/v3/klines?symbol=' + sym + '&interval=1d&limit=' + BACKFILL_DAYS);
                        if (!r.ok) continue;
                        const d = await r.json();
                        if (Array.isArray(d) && d.length) { klines = d; used = sym; break; }
                    } catch (_) { /* try next symbol */ }
                }
                if (klines) {
                    let xrp = 0, usd = 0, tx = 0, days = 0;
                    klines.forEach(function(k){
                        const day = new Date(k[0]).toISOString().split('T')[0];
                        const bx  = parseFloat(k[5]) || 0;   // base volume  = XRP
                        const qv  = parseFloat(k[7]) || 0;   // quote volume = USD
                        const nt  = parseInt(k[8], 10) || 0; // trade count
                        xrp += bx; usd += qv; tx += nt; days++;
                        h.daily[day] = h.daily[day] || {};
                        h.daily[day].exchXrp = bx;
                        h.daily[day].exchUsd = qv;
                    });
                    h.exch = { xrp:xrp, usd:usd, tx:tx, days:days, updated:new Date().toISOString(),
                               source:'Binance.US ' + used + ' 1d', status:'ok' };
                } else {
                    h.exch.status = 'unavailable';
                    h.exch.updated = new Date().toISOString();
                }
                saveBlackbox();
                // On-chain: actually search the ledger via the live WS uplink
                // (sums real XRP payment volume across the main exchange wallets).
                scanChainVolume();
            } catch (e) {
                console.error('backfillHistory failed', e);
                h.exch.status = 'error';
            } finally {
                _backfillRunning = false;
                _setBackfillLoading(false);
                renderHistoryBanner();
            }
        }

        function _setBackfillLoading(on) {
            const list = document.getElementById('report-list');
            if (!list) return;
            let el = document.getElementById('hist-loading');
            if (on) {
                if (!el) {
                    el = document.createElement('div');
                    el.id = 'hist-loading';
                    el.className = 'text-center text-gray-500 mt-6 font-tech text-xs tracking-widest';
                    list.insertBefore(el, list.firstChild);
                }
                el.innerHTML = '<span style="color:var(--lime-main)">&#9700;&#9701;</span> LOADING HISTORICAL VOLUME (365D)&hellip;';
            } else if (el) {
                el.remove();
            }
        }

        function renderHistoryBanner() {
            const list = document.getElementById('report-list');
            if (!list) return;
            const h = _ensureHistory();
            const old = document.getElementById('hist-banner');
            if (old) old.remove();
            const exch = h.exch, chain = h.chain;
            const exchLine = (exch.status === 'ok')
                ? (_xrpShort(exch.xrp) + ' XRP &nbsp;|&nbsp; $' + _xrpShort(exch.usd) + ' &nbsp;|&nbsp; ' + exch.days + 'd')
                : (exch.status === 'unavailable' ? 'feed unavailable' : exch.status);
            let chainLine;
            if (chain.status === 'scanning') chainLine = '<span style="color:var(--lime-main)">&#9685;</span> scanning ledger&hellip;';
            else if (chain.status === 'ok') chainLine = _xrpShort(chain.xrp) + ' XRP | ' + (chain.tx||0) + ' tx | ' + (chain.wallets||0) + ' wallets' + (chain.spanDays ? (' | ~' + chain.spanDays + 'd') : '');
            else chainLine = (chain.status || 'pending');
            // Drop the "WAITING…" placeholder once we have real data to show.
            if (list.innerText.indexOf('WAITING') !== -1) {
                Array.from(list.children).forEach(function(c){ if (c.innerText && c.innerText.indexOf('WAITING') !== -1) c.remove(); });
            }
            const banner = document.createElement('div');
            banner.id = 'hist-banner';
            banner.style.cssText = "margin:8px;padding:10px;border:1px solid var(--lime-dim);border-radius:8px;background:rgba(0,18,0,0.85);font-family:'Share Tech Mono';";
            banner.innerHTML =
                '<div style="font-size:9px;letter-spacing:1px;color:#55aa55;margin-bottom:6px;">HISTORICAL VOLUME &mdash; 365D BACKFILL</div>' +
                '<div style="display:flex;justify-content:space-between;font-size:11px;color:#00ff00;padding:3px 0;"><span>EXCHANGE (Binance)</span><span>' + exchLine + '</span></div>' +
                '<div style="display:flex;justify-content:space-between;font-size:11px;color:#00cccc;padding:3px 0;"><span>ON-CHAIN (main wallets)</span><span>' + chainLine + '</span></div>' +
                '<div style="font-size:8px;color:#557755;margin-top:5px;line-height:1.4;">Exchange = market trading volume (Binance, backfilled). On-chain = real XRP payment volume sampled live from the main exchange wallets via account_tx.</div>';
            list.insertBefore(banner, list.firstChild);
        }

        // On-chain volume: actually search the ledger. We already hold a live WS
        // uplink, so query account_tx for the main exchange wallets and sum real
        // XRP payment volume over the returned window — no guessing/claiming.
        const CHAIN_SCAN_LIMIT = 200;      // txs pulled per wallet
        const CHAIN_SCAN_WALLETS = 60;     // covers all main (EXCH) wallets
        const CHAIN_SCAN_TIMEOUT = 35000;  // ms before finalizing with whatever arrived
        let _chainScan = null;

        function _mainWallets() {
            try {
                return (PRELOADED_HVTS || [])
                    .filter(function(w){ return w && w.type === 'EXCH' && w.address; })
                    .slice(0, CHAIN_SCAN_WALLETS);
            } catch (_) { return []; }
        }

        function scanChainVolume(force) {
            const h = _ensureHistory();
            const todayKey = new Date().toISOString().split('T')[0];
            // Already scanned today → instant, no spinner ("been here the day before").
            if (!force && h.chain.updated && h.chain.updated.split('T')[0] === todayKey && h.chain.status === 'ok') return;
            if (_chainScan && _chainScan.active) return;
            // Uplink not ready yet — retry a few times, then give up quietly.
            if (!socket || socket.readyState !== WebSocket.OPEN) {
                _chainScan = _chainScan || { retries: 0 };
                if ((_chainScan.retries = (_chainScan.retries || 0) + 1) <= 12) {
                    setTimeout(function(){ scanChainVolume(force); }, 2500);
                }
                return;
            }
            const wallets = _mainWallets();
            if (!wallets.length) return;
            _chainScan = { active:true, xrp:0, tx:0, minDate:null, maxDate:null, pending:{}, done:0, retries:0 };
            wallets.forEach(function(w){ _chainScan.pending[w.address] = 1; });
            h.chain.status = 'scanning';
            _setBackfillLoading(true);
            renderHistoryBanner();
            var i = 0;
            wallets.forEach(function(w){
                setTimeout(function(){
                    if (!socket || socket.readyState !== WebSocket.OPEN) { _chainScanDone(w.address); return; }
                    try {
                        socket.send(JSON.stringify({ id:'cvol_' + w.address, command:'account_tx',
                            account:w.address, ledger_index_min:-1, ledger_index_max:-1,
                            limit:CHAIN_SCAN_LIMIT, forward:false }));
                    } catch (e) { _chainScanDone(w.address); }
                }, (i++) * 140);
            });
            // Safety: finalize even if some wallets never answer.
            _chainScan.timer = setTimeout(_chainScanFinalize, CHAIN_SCAN_TIMEOUT);
        }

        function _chainScanDone(addr) {
            if (!_chainScan || !_chainScan.active) return;
            if (_chainScan.pending[addr]) { delete _chainScan.pending[addr]; _chainScan.done++; }
            if (Object.keys(_chainScan.pending).length === 0) _chainScanFinalize();
        }

        // Routed here from the WS onmessage handler for ids starting "cvol_".
        function handleChainVolResp(d) {
            if (!_chainScan || !_chainScan.active) return;
            var addr = d.id.replace('cvol_', '');
            try {
                var txs = (d.result && d.result.transactions) || [];
                txs.forEach(function(entry){
                    var tx = entry.tx || entry.tx_json || entry;
                    var meta = entry.meta || entry.metaData;
                    if (!tx || tx.TransactionType !== 'Payment') return;
                    // Prefer the amount actually delivered; fall back to Amount.
                    var amt = (meta && (meta.delivered_amount || meta.DeliveredAmount)) || tx.Amount;
                    if (typeof amt !== 'string') return; // object ⇒ issued currency, not XRP
                    var xrp = parseFloat(amt) / 1000000;
                    if (!isFinite(xrp) || xrp <= 0) return;
                    _chainScan.xrp += xrp; _chainScan.tx++;
                    if (typeof tx.date === 'number') {
                        var ms = (tx.date + 946684800) * 1000; // XRPL epoch → unix ms
                        if (_chainScan.minDate === null || ms < _chainScan.minDate) _chainScan.minDate = ms;
                        if (_chainScan.maxDate === null || ms > _chainScan.maxDate) _chainScan.maxDate = ms;
                    }
                });
            } catch (e) { console.error('chain vol parse', e); }
            _chainScanDone(addr);
        }

        function _chainScanFinalize() {
            if (!_chainScan || !_chainScan.active) return;
            if (_chainScan.timer) { clearTimeout(_chainScan.timer); _chainScan.timer = null; }
            _chainScan.active = false;
            var h = _ensureHistory();
            var spanDays = (_chainScan.minDate && _chainScan.maxDate)
                ? Math.max(1, Math.round((_chainScan.maxDate - _chainScan.minDate) / 86400000)) : 0;
            h.chain = {
                xrp: Math.floor(_chainScan.xrp), tx: _chainScan.tx, wallets: _chainScan.done,
                spanDays: spanDays, source: 'XRPL account_tx (main wallets)',
                status: 'ok', updated: new Date().toISOString()
            };
            saveBlackbox();
            _setBackfillLoading(false);
            renderHistoryBanner();
        }

        function _histReportText() {
            try {
                var h = _ensureHistory(), e = h.exch, c = h.chain;
                var el = (e.status === 'ok')
                    ? (Math.floor(e.xrp).toLocaleString() + ' XRP / $' + Math.floor(e.usd).toLocaleString() + ' / ' + e.days + 'd')
                    : ('UNAVAILABLE (' + e.status + ')');
                var cl = (c.status === 'ok')
                    ? (Math.floor(c.xrp||0).toLocaleString() + ' XRP / ' + (c.tx||0) + ' tx / ' + (c.wallets||0) + ' wallets' + (c.spanDays ? (' / ~' + c.spanDays + 'd') : ''))
                    : (c.status === 'scanning' ? 'SCANNING LEDGER…' : (c.status || 'pending'));
                return '> EXCHANGE (Binance): ' + el +
                       '\n> ON-CHAIN (main wallets): ' + cl;
            } catch (_) { return '> (no historical data)'; }
        }

        // Shadow intel tx-family counter: live ledger activity by family, for the intel report.
        function _txnFamiliesText() {
            try {
                if (!window.SW || !SW.txn) return '> (counter unavailable)';
                var s = SW.txn.snapshot();
                if (!s.total) return '> (no transactions observed yet)';
                var lines = SW.txn.FAMILY_NAMES.map(function (f) {
                    var d = s.families[f];
                    return '> ' + (d.label + ':').padEnd(10, ' ') + String(d.count).padStart(7, ' ') + '  (' + d.pct + '%)';
                });
                lines.push('> ' + 'TOTAL:'.padEnd(10, ' ') + String(s.total).padStart(7, ' ') + (s.other ? ('  (+' + s.other + ' other)') : ''));
                return lines.join('\n');
            } catch (_) { return '> (counter error)'; }
        }

