        function updateGraph() {
            if (!graphActive || !graphCanvas) return;
            requestAnimationFrame(updateGraph);
            
            // AUTO-RESIZE LOGIC (GRAPH) - Fixes squishing on mobile
            if (graphCanvas.width !== graphCanvas.offsetWidth || graphCanvas.height !== graphCanvas.offsetHeight) {
                graphCanvas.width = graphCanvas.offsetWidth;
                graphCanvas.height = graphCanvas.offsetHeight;
            }
            
            graphCtx.setTransform(1, 0, 0, 1, 0, 0); // Reset for clear
            graphCtx.fillStyle = "#000500";
            graphCtx.fillRect(0,0, graphCanvas.width, graphCanvas.height);

            // Apply Zoom/Pan
            graphCtx.setTransform(graphZoom, 0, 0, graphZoom, (graphCanvas.width/2) + graphPan.x, (graphCanvas.height/2) + graphPan.y);

            // PHYSICS
            for (let i=0; i<graphNodes.length; i++) {
                let n1 = graphNodes[i];
                for (let j=i+1; j<graphNodes.length; j++) {
                    let n2 = graphNodes[j];
                    let dx = n1.x - n2.x;
                    let dy = n1.y - n2.y;
                    let dist = Math.sqrt(dx*dx + dy*dy) || 1;
                    if (dist < 150) {
                        let f = 200 / (dist * dist);
                        let fx = (dx/dist) * f;
                        let fy = (dy/dist) * f;
                        n1.vx += fx; n1.vy += fy;
                        n2.vx -= fx; n2.vy -= fy;
                    }
                }
                let dx = 0 - n1.x; // Gravity to (0,0)
                let dy = 0 - n1.y;
                n1.vx += dx * 0.005;
                n1.vy += dy * 0.005;
                n1.vx *= 0.9; n1.vy *= 0.9; 
                if(n1.type !== 'CENTER' || graphNodes.length === 1) { 
                    n1.x += n1.vx;
                    n1.y += n1.vy;
                }
            }

            // Draw Edges
            graphCtx.strokeStyle = "#004400";
            graphCtx.lineWidth = 1/graphZoom; // Keep line width consistent visually
            graphEdges.forEach(e => {
                let s = graphNodes.find(n => n.id === e.source);
                let t = graphNodes.find(n => n.id === e.target);
                if(s && t) {
                    graphCtx.beginPath();
                    graphCtx.moveTo(s.x, s.y);
                    graphCtx.lineTo(t.x, t.y);
                    graphCtx.stroke();
                }
            });

            // Draw Nodes
            graphNodes.forEach(n => {
                graphCtx.beginPath();
                let r = (n.type==='CENTER'?8:5) / Math.sqrt(graphZoom); // Adjust size slightly
                r = Math.max(r, 2);
                graphCtx.arc(n.x, n.y, r, 0, Math.PI*2);
                graphCtx.fillStyle = n.color;
                graphCtx.fill();
                
                // Text scale
                if(graphZoom > 0.5) {
                    graphCtx.fillStyle = "#fff";
                    graphCtx.font = `${8/graphZoom}px monospace`;
                    graphCtx.fillText(n.id.substring(0,4), n.x-(10/graphZoom), n.y-(10/graphZoom));
                }
            });
        }

