        function refreshHVTBalances() {
            // v16.7.0 back-compat shim: ONE safe capped pass over the ACTIVE set only (NEVER the 1000 cold DB).
            if(!socket || socket.readyState !== WebSocket.OPEN) return;
            getActiveScanList().forEach(function(addr,i){ setTimeout(function(){ _sendBalReq(addr); }, i*120); });
        }

        // ── v16.7.0-wallet-intel1 — throttled, queued, socket-safe balance scanner ──
        // Scans ONLY the active HVT set (PRELOADED + custom). NEVER the 1000-wallet cold DB.
        var _scanState = { idx:0, running:false, cancelled:false, lastFullPass:0 };
        var SCAN_BATCH = 6;            // capped concurrency per tick
        var SCAN_TICK_MS = 1400;       // gap between batches
        var SCAN_COOLDOWN_MS = 25000;  // rest after a full pass (no stacking sweeps)
        var SCAN_RECONNECT_MS = 4000;  // wait + retry if socket not open (backoff)
        function getActiveScanList(){
            var seen={}, out=[];
            PRELOADED_HVTS.forEach(function(h){ if(h&&h.address&&!seen[h.address]){seen[h.address]=1;out.push(h.address);} });
            customHvts.forEach(function(c){ if(c&&c.address&&!seen[c.address]){seen[c.address]=1;out.push(c.address);} });
            return out;
        }
        function _sendBalReq(addr){
            try{
                if(!socket || socket.readyState !== WebSocket.OPEN) return false;
                socket.send(JSON.stringify({ id:"bal_"+addr, command:"account_info", account:addr, ledger_index:"validated" }));
                return true;
            }catch(e){ return false; }
        }
        function _scanTick(){
            if(_scanState.cancelled){ _scanState.running=false; return; }
            if(!socket || socket.readyState !== WebSocket.OPEN){ setTimeout(_scanTick, SCAN_RECONNECT_MS); return; }
            var list=getActiveScanList();
            if(!list.length){ setTimeout(_scanTick, SCAN_COOLDOWN_MS); return; }
            if(_scanState.idx >= list.length){ _scanState.idx=0; _scanState.lastFullPass=Date.now(); setTimeout(_scanTick, SCAN_COOLDOWN_MS); return; }
            var end=Math.min(_scanState.idx+SCAN_BATCH, list.length);
            for(var i=_scanState.idx;i<end;i++){ _sendBalReq(list[i]); }
            _scanState.idx=end;
            setTimeout(_scanTick, SCAN_TICK_MS);
        }
        function startThrottledScanner(){
            if(_scanState.running) return;
            _scanState.running=true; _scanState.cancelled=false; _scanState.idx=0;
            setTimeout(_scanTick, 1200);
        }
        function refreshVisibleBalances(){
            // on-demand: refresh only HVT rows currently in the DOM (cheap)
            if(!socket || socket.readyState !== WebSocket.OPEN) return;
            var rows=document.querySelectorAll('#hvt-list [id^="bal-"]'); var i=0;
            rows.forEach(function(el){ var a=el.id.replace('bal-',''); setTimeout(function(){ _sendBalReq(a); }, (i++)*120); });
        }

