        function init3D() {
            const container = document.getElementById('canvas-container');
            if (!container) return;
            // Fail-safe: the 3D particle background is purely decorative. If three.js
            // didn't load (CDN blocked/slow) or the device can't create a WebGL context
            // (low-end phones, hardware acceleration off), skip it silently instead of
            // throwing — a throw here would abort app init and stall scans/reports.
            if (typeof THREE === 'undefined') { try { console.warn('[3D] three.js unavailable — skipping background.'); } catch(_){} return; }
            try {
                scene = new THREE.Scene(); scene.fog = new THREE.FogExp2(0x000000, 0.01);
                camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
                camera.position.set(0, -10, 30); camera.lookAt(0, 10, 0);
                renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
                renderer.setSize(window.innerWidth, window.innerHeight);
                container.appendChild(renderer.domElement);
                const pGeo = new THREE.BufferGeometry();
                const pos = [], speeds = [];
                for(let i=0; i<particleCount; i++) {
                    pos.push((Math.random()-0.5)*50, (Math.random()-0.5)*10-20, (Math.random()-0.5)*30);
                    speeds.push(0.1 + Math.random() * 0.4);
                }
                pGeo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
                pGeo.setAttribute('speed', new THREE.Float32BufferAttribute(speeds, 1));
                particles = new THREE.Points(pGeo, new THREE.PointsMaterial({ color: 0x00ff00, size: 0.4, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending }));
                scene.add(particles);
                animate();
                window.addEventListener('resize', () => { try { camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix(); renderer.setSize(window.innerWidth, window.innerHeight); } catch(_){} });
            } catch (e) {
                particles = null;
                try { console.warn('[3D] background init failed — continuing without it:', e && e.message); } catch(_){}
            }
        }
        function animate() {
            requestAnimationFrame(animate);
            // The PC live wall covers this decorative starfield completely. Skip
            // the 2500-particle update and the WebGL draw while it is up, but keep
            // the chain alive so resuming is instant and no restart race exists.
            if (window.__swStarsPaused) return;
            if (!particles) return;
            const pos = particles.geometry.attributes.position.array;
            const spd = particles.geometry.attributes.speed.array;
            for(let i=0; i<particleCount; i++) { pos[i*3+1] += spd[i]; if(pos[i*3+1] > 30) { pos[i*3+1] = -20; pos[i*3] = (Math.random()-0.5)*50; } }
            particles.geometry.attributes.position.needsUpdate = true;
            camera.position.x = Math.sin(Date.now()*0.0005)*2;
            renderer.render(scene, camera);
        } 

        function resizeMap() {
            if(!mapCanvas || !mapCanvas.offsetParent) return;
            mapCanvas.width = mapCanvas.offsetWidth;
            mapCanvas.height = mapCanvas.offsetHeight;
        } 

        function setupMapInteractions() {
            mapCanvas.addEventListener('mousedown', (e) => {
                mapIsDragging = true;
                mapLastPos = { x: e.clientX, y: e.clientY };
            });
            window.addEventListener('mouseup', () => mapIsDragging = false);
            mapCanvas.addEventListener('mousemove', (e) => {
                if (!mapIsDragging) return;
                const dx = e.clientX - mapLastPos.x;
                const dy = e.clientY - mapLastPos.y;
                mapCamera.x += dx;
                mapCamera.y += dy;
                mapLastPos = { x: e.clientX, y: e.clientY };
            });
            mapCanvas.addEventListener('wheel', (e) => {
                e.preventDefault();
                const scaleAmount = 1.1;
                const mouseX = e.offsetX;
                const mouseY = e.offsetY;
                if (e.deltaY < 0) {
                    mapCamera.zoom *= scaleAmount;
                    mapCamera.x -= (mouseX - mapCamera.x) * (scaleAmount - 1);
                    mapCamera.y -= (mouseY - mapCamera.y) * (scaleAmount - 1);
                } else {
                    mapCamera.zoom /= scaleAmount;
                    mapCamera.x += (mouseX - mapCamera.x) * (1 - 1/scaleAmount);
                    mapCamera.y += (mouseY - mapCamera.y) * (1 - 1/scaleAmount);
                }
            }, {passive: false}); 

            // Touch
            mapCanvas.addEventListener('touchstart', e => {
                if (e.touches.length === 1) {
                    mapIsDragging = true;
                    mapLastPos = { x: e.touches[0].clientX, y: e.touches[0].clientY };
                } else if (e.touches.length === 2) {
                    mapIsDragging = false;
                    const dx = e.touches[0].clientX - e.touches[1].clientX;
                    const dy = e.touches[0].clientY - e.touches[1].clientY;
                    mapTouchDist = Math.hypot(dx, dy);
                }
            });
            mapCanvas.addEventListener('touchmove', e => {
                e.preventDefault();
                if (e.touches.length === 1 && mapIsDragging) {
                    const dx = e.touches[0].clientX - mapLastPos.x;
                    const dy = e.touches[0].clientY - mapLastPos.y;
                    mapCamera.x += dx;
                    mapCamera.y += dy;
                    mapLastPos = { x: e.touches[0].clientX, y: e.touches[0].clientY };
                } else if (e.touches.length === 2) {
                    const dx = e.touches[0].clientX - e.touches[1].clientX;
                    const dy = e.touches[0].clientY - e.touches[1].clientY;
                    const dist = Math.hypot(dx, dy);
                    const centerX = (e.touches[0].clientX + e.touches[1].clientX) / 2;
                    const centerY = (e.touches[0].clientY + e.touches[1].clientY) / 2;
                    const rect = mapCanvas.getBoundingClientRect();
                    const mouseX = centerX - rect.left;
                    const mouseY = centerY - rect.top;
                    const zoomFactor = dist / mapTouchDist;
                    mapCamera.zoom *= zoomFactor;
                    mapCamera.x -= (mouseX - mapCamera.x) * (zoomFactor - 1);
                    mapCamera.y -= (mouseY - mapCamera.y) * (zoomFactor - 1);
                    mapTouchDist = dist;
                }
            });
            
            // Map Click
            mapCanvas.addEventListener('click', (e) => {
                const rect = mapCanvas.getBoundingClientRect();
                const mouseX = e.clientX - rect.left;
                const mouseY = e.clientY - rect.top;
                const worldX = (mouseX - mapCamera.x) / mapCamera.zoom;
                const worldY = (mouseY - mapCamera.y) / mapCamera.zoom; 

                for (let i = bubbles.length - 1; i >= 0; i--) {
                    let b = bubbles[i];
                    let visible = true;
                    if (activeFilter === 'small' && (b.isL2 || b.val >= 100000)) visible = false;
                    if (activeFilter === 'whale' && (b.isL2 || b.val < 100000)) visible = false;
                    if (activeFilter === 'l2' && !b.isL2) visible = false;
                    if (visible && Math.hypot(b.x - worldX, b.y - worldY) < b.radius + 10) { openModal(b); bubbles.splice(i, 1); break; }
                }
            });
        } 

        class Bubble {
            constructor(label, val, color, hash, from, to, type, issuer) {
                this.x = (Math.random() * mapCanvas.width * 3) - mapCanvas.width; 
                this.y = mapCanvas.height + 100;
                let safeVal = parseFloat(val) || 1; 
                this.radius = Math.max(10, Math.min(50, Math.log(safeVal + 10) * 3));
                this.speed = 1 + Math.random() * 2;
                this.color = color;
                this.hash = hash;
                this.label = type === 'L2' ? label : val.toLocaleString(undefined, {minimumFractionDigits: 0, maximumFractionDigits: 4});
                this.val = val; this.from = from; this.to = to; this.type = type; this.life = 1.0;
                this.isL2 = type === 'L2' && issuer;
                this.icon = null; this.iconLoaded = false;
                if (this.isL2) {
                    this.icon = new Image();
                    this.icon.crossOrigin = "Anonymous";
                    this.icon.src = `https://xumm.app/avatar/${issuer}_200.png`;
                    this.icon.onload = () => { this.iconLoaded = true; };
                    this.icon.onerror = () => { this.iconLoaded = false; this.icon = null; };
                }
            }
            update() { this.y -= this.speed; this.life -= 0.002; }
            draw() {
                mapCtx.globalAlpha = this.life;
                mapCtx.beginPath(); mapCtx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
                if (this.isL2 && this.iconLoaded && this.icon) {
                    mapCtx.save(); mapCtx.clip(); mapCtx.drawImage(this.icon, this.x - this.radius, this.y - this.radius, this.radius * 2, this.radius * 2); mapCtx.restore();
                } else {
                    mapCtx.fillStyle = this.color; mapCtx.fill();
                }
                mapCtx.strokeStyle = "#fff"; mapCtx.lineWidth = 1; mapCtx.stroke();
                if ((this.radius * mapCamera.zoom) > 8) {
                    mapCtx.textAlign = "center"; mapCtx.font = "bold 9px monospace";
                    mapCtx.lineWidth = 3; mapCtx.strokeStyle = "black"; mapCtx.strokeText(this.label, this.x, this.y + 3);
                    mapCtx.fillStyle = "#fff"; mapCtx.fillText(this.label, this.x, this.y + 3);
                }
            }
        }
        function loopMap() {
            if (!mapActive || !mapCanvas) return;
            requestAnimationFrame(loopMap);
            
            if (mapCanvas.width !== mapCanvas.offsetWidth || mapCanvas.height !== mapCanvas.offsetHeight) {
                mapCanvas.width = mapCanvas.offsetWidth;
                mapCanvas.height = mapCanvas.offsetHeight;
            }
            
            mapCtx.setTransform(1, 0, 0, 1, 0, 0);
            mapCtx.clearRect(0, 0, mapCanvas.width, mapCanvas.height);
            mapCtx.setTransform(mapCamera.zoom, 0, 0, mapCamera.zoom, mapCamera.x, mapCamera.y); 

            for (let i = bubbles.length - 1; i >= 0; i--) {
                let b = bubbles[i]; 
                let shouldDraw = true;
                if (activeFilter === 'small' && (b.isL2 || b.val >= 100000)) shouldDraw = false;
                if (activeFilter === 'whale' && (b.isL2 || b.val < 100000)) shouldDraw = false; 
                if (activeFilter === 'l2' && !b.isL2) shouldDraw = false;
                b.update(); 
                if (shouldDraw) b.draw();
                if (b.y < -500 || b.life <= 0) bubbles.splice(i, 1);
            }
        } 

        // --- WEBSOCKET ---
        document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible' && isConnected && (!socket || socket.readyState !== WebSocket.OPEN)) { showToast("RE-ESTABLISHING UPLINK..."); startXRPL(); } });
        setInterval(() => { if (isConnected && socket && socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify({command: "ping"})); }, 15000);
        setInterval(() => { if (isConnected && (Date.now() - lastHeartbeat > 45000)) { showToast("SIGNAL LOST. RECONNECTING..."); startXRPL(); } }, 5000); 

        function startXRPL() {
            if(socket) {
                socket.onclose = null;
                socket.onerror = null;
                socket.onmessage = null;
                socket.onopen = null;
                socket.close();
                socket = null;
            } 

            const server = XRPL_SERVERS[currentServerIndex];
            
            const serverName = server.split('//')[1].split('.')[0].toUpperCase();
            const statusEl = document.getElementById('status-text');
            if(statusEl) statusEl.innerText = `CONNECTING [${serverName}]...`;
            
            try {
                socket = new WebSocket(server);
            } catch (e) {
                console.error("WS Init Fail", e);
                retryConnection();
                return;
            }
            
            socket.onopen = () => { 
                socket.send(JSON.stringify({command:"subscribe", streams:["transactions", "ledger"]})); 
                lastHeartbeat = Date.now();
                if(statusEl) {
                    statusEl.innerText = `ACTIVE [${serverName}]`;
                    statusEl.classList.replace('text-yellow-500', 'text-green-500');
                }
            };
            
            socket.onmessage = (e) => { 
                lastHeartbeat = Date.now(); 
                let d;
                try { d = JSON.parse(e.data); } catch(err){ return; }
                if(d.type==='transaction') handleTx(d.transaction, d.meta); 
                if(d.type==='ledgerClosed' && document.getElementById('ledger-display')) document.getElementById('ledger-display').innerText = d.ledger_index; 
                if(d.result && d.result.transactions && !(d.id && (d.id.indexOf("cvol_") === 0 || d.id.indexOf("risk_") === 0 || d.id.indexOf("esc_") === 0))) processTrace(d.result.account, d.result.transactions);

                if(d.id && d.id.indexOf("cvol_") === 0) { handleChainVolResp(d); return; }
                if(d.id && d.id.indexOf("risk_") === 0) { if(window.__riskOnMessage) window.__riskOnMessage(d); return; }
                if(d.id && d.id.indexOf("esc_") === 0) { if(window.SW_ESCROW) SW_ESCROW.handleResp(d); return; }

                if(d.id && d.id.startsWith("bal_")) {
                    const acc = d.id.replace("bal_", "");
                    const el = document.getElementById('bal-' + acc);
                    const row = document.getElementById('row-' + acc);
                    
                    if(el && row) {
                        if (d.error === 'actNotFound') {
                            el.innerText = "[INACTIVE]";
                            el.style.color = "#666";
                            row.classList.add('inactive');
                        } else if(d.result && d.result.account_data) {
                            const bal = parseFloat(d.result.account_data.Balance) / 1000000;
                            if(bal < 1) {
                                el.innerText = "EMPTY";
                                el.style.color = "#666";
                                row.classList.add('inactive');
                            } else {
                                el.innerText = bal.toLocaleString(undefined, {minimumFractionDigits: 6, maximumFractionDigits: 6});
                                el.style.color = "#00ff00";
                                row.classList.remove('inactive');
                            }
                        }
                    }
                }
            };
            
            socket.onclose = (e) => { 
                if(isConnected) retryConnection();
            };
            
            socket.onerror = (e) => {
            };
        } 

        function retryConnection() {
            const statusEl = document.getElementById('status-text');
            if(statusEl) {
                statusEl.innerText = "SIGNAL LOST. REROUTING...";
                statusEl.classList.replace('text-green-500', 'text-yellow-500');
            }
            currentServerIndex = (currentServerIndex + 1) % XRPL_SERVERS.length;
            setTimeout(startXRPL, 2000);
        } 

        function processTrace(centerAccount, txs) {
            let center = graphNodes.find(n => n.id === centerAccount);
            if(!center) {
                center = {id: centerAccount, x: 0, y: 0, type: 'CENTER', color: '#ffd700', vx:0, vy:0};
                graphNodes.push(center);
            } 

            txs.forEach(t => {
                const tx = t.tx;
                let other = null;
                let color = '#00ff00'; 
                
                if (tx.Account === centerAccount) {
                    other = tx.Destination;
                    color = '#ffaa00'; 
                } else {
                    other = tx.Account;
                    color = '#00ffff'; 
                } 

                if(other && !graphNodes.find(n => n.id === other)) {
                    graphNodes.push({
                        id: other,
                        x: center.x + (Math.random()-0.5)*100,
                        y: center.y + (Math.random()-0.5)*100,
                        type: 'SAT',
                        color: color,
                        vx: 0, vy: 0
                    });
                    graphEdges.push({source: centerAccount, target: other});
                }
            });
        } 

        function hexToASCII(hex) {
            let str = ''; for (let i = 0; i < hex.length; i += 2) str += String.fromCharCode(parseInt(hex.substr(i, 2), 16)); return str.replace(/\0/g, '');
        } 

        function getReportType(amt, known) { 
            if(known) return 'I'; 
            if(amt>5000000) return 'S'; 
            return 'R'; 
        }
        function getOutflow(fromKnown, toKnown) { 
            if(fromKnown && !toKnown) return 'EXCH-OUT'; 
            if(!fromKnown && toKnown) return 'EXCH-IN'; 
            if(fromKnown && toKnown) return 'INTER-EXCH'; 
            return 'P2P'; 
        } 

        function handleTx(tx, meta) {
            if (isPaused) return;

            // Shadow intel: count every validated tx type into families (Money/Markets/NFTs/Accounts)
            try { if (window.SW && SW.txn) SW.txn.record(tx.TransactionType); } catch(e){}
            // Safe HTML escaper for live-XRPL-derived strings (token names, etc.)
            var SWE = (window.SW && SW.escapeHtml) ? SW.escapeHtml : function(x){ return String(x==null?'':x); };
            // Shadow intel: classify the flow/route for this tx (read-only label)
            var _flow = null; try { if (window.SW && SW.flow) _flow = SW.flow.classify(tx, meta); } catch(e){}

            if (tx.TransactionType === 'TrustSet') {
                const currency = tx.LimitAmount.currency;
                if (currency === 'RLUSD' || currency.startsWith('524C555344')) {
                    metrics.trustLines++; metrics.rlusdLines++;
                    const feed = document.getElementById('feed');
                    const row = document.createElement('div');
                    row.className = "tx-row";
                    row.innerHTML = `<div class="row-top text-cyan-400"><div class="flex items-center gap-2"><span class="font-bold text-base text-shadow-lime">RLUSD TRUST LINE</span><span class="tag-pill tag-trust">INFRASTRUCTURE</span></div><div class="text-[10px] font-mono text-gray-500">${new Date().toLocaleTimeString()}</div></div><div class="flex justify-between text-[11px] font-mono text-gray-400"><span>${tx.Account.substring(0,8)}... ACTIVATED</span></div>`;
                    feed.prepend(row);
                    if(feed.children.length > 40) feed.lastChild.remove();
                } else { metrics.trustLines++; }
                return;
            } 

            // ── ESCROW UNLOCK / LOCK (catches Ripple's monthly escrow releases) ──
            if (tx.TransactionType === 'EscrowFinish' || tx.TransactionType === 'EscrowCreate') {
                if (meta && meta.TransactionResult && meta.TransactionResult !== 'tesSUCCESS') return;
                var isFinish = (tx.TransactionType === 'EscrowFinish');
                var escXrp = 0, escOwner = tx.Account, escDest = null;
                try {
                    var _nodes = (meta && meta.AffectedNodes) || [];
                    for (var _i = 0; _i < _nodes.length; _i++) {
                        var _n = _nodes[_i].DeletedNode || _nodes[_i].CreatedNode;
                        if (_n && _n.LedgerEntryType === 'Escrow') {
                            var _ff = _n.FinalFields || _n.NewFields || {};
                            if (typeof _ff.Amount === 'string') escXrp = parseInt(_ff.Amount, 10) / 1000000;
                            if (_ff.Destination) escDest = _ff.Destination;
                            if (_ff.Account) escOwner = _ff.Account;
                            break;
                        }
                    }
                } catch (e) {}
                if (!isFinish && escXrp <= 0 && typeof tx.Amount === 'string') escXrp = parseInt(tx.Amount, 10) / 1000000;
                if (!(escXrp > 0)) return;  // non-XRP or undeterminable escrow
                var escTo = isFinish ? (escDest || escOwner) : escOwner;
                var eFromName = (KNOWN_WALLETS[escOwner] && KNOWN_WALLETS[escOwner].name) || null;
                var eToName = (KNOWN_WALLETS[escTo] && KNOWN_WALLETS[escTo].name) || null;
                var eLabel = isFinish ? 'ESCROW UNLOCK' : 'ESCROW LOCK';
                // Persist into the Escrow Watch panel (read-only, deduped by hash).
                try { if (window.SW_ESCROW) SW_ESCROW.record({ hash: tx.hash, type: isFinish ? 'UNLOCK' : 'LOCK', xrp: Math.floor(escXrp), owner: escOwner, dest: isFinish ? (escDest || null) : null, ts: (typeof tx.date === 'number' ? (tx.date + 946684800) * 1000 : Date.now()), ledger: tx.ledger_index || null }); } catch (e) {}

                var efeed = document.getElementById('feed');
                if (efeed) {
                    if (efeed.innerText.includes('AWAITING')) efeed.innerHTML = '';
                    var erow = document.createElement('div'); erow.className = 'tx-row';
                    var eColor = isFinish ? 'text-yellow-300' : 'text-orange-400';
                    erow.innerHTML = '<div class="row-top ' + eColor + '"><div class="flex items-center gap-2"><span class="font-bold text-base text-shadow-lime">' + escXrp.toLocaleString(undefined, { maximumFractionDigits: 6 }) + ' XRP</span><span class="tag-pill ' + (isFinish ? 'tag-hvt' : 'tag-dep') + '">' + eLabel + '</span></div><div class="text-[10px] font-mono text-gray-500">' + new Date().toLocaleTimeString() + '</div></div><div class="flex justify-between text-[11px] font-mono text-gray-400"><span>' + SWE(eFromName || (escOwner ? escOwner.substring(0, 8) + '…' : '?')) + ' ➔ ' + SWE(eToName || (escTo ? escTo.substring(0, 8) + '…' : '?')) + '</span></div><div class="btn-row"><button class="action-btn trace-btn" onclick="traceWallet(\'' + escTo + '\')">TRACE</button><button class="action-btn" onclick="openScan(\'' + tx.hash + '\')">SCAN</button></div>';
                    efeed.prepend(erow);
                    if (efeed.children.length > 40) efeed.lastChild.remove();
                }
                if (escXrp >= 100000) {
                    var eRep = { hash: tx.hash, amt: escXrp, wallet: eToName || escTo || escOwner, type: eLabel, out: getOutflow(eFromName, eToName), time: new Date().toISOString() };
                    renderReportRow(eRep);
                    if (!blackbox.whaleHits) blackbox.whaleHits = [];
                    blackbox.whaleHits.unshift(eRep);
                    if (blackbox.whaleHits.length > 100) blackbox.whaleHits.pop();
                    saveCase({ hash: tx.hash, amt: escXrp, from: eFromName || escOwner, to: eToName || escTo, type: eLabel });
                    triggerWhaleAlert(); playAlert('HVT');
                    blackbox.txCount++; saveBlackbox();
                }
                return;
            }

            if (tx.TransactionType !== 'Payment' && tx.TransactionType !== 'OfferCreate') return;
            
            let isSuccess = meta?.TransactionResult === 'tesSUCCESS';
            const hideFailed = document.getElementById('hide-failed').checked;
            if (hideFailed && !isSuccess) return; 

            let type = "TSFR"; let color = "text-green-500"; let mapColor = "#00ff00"; let amt = 0; let isL2 = false; let tokenName = "XRP"; let issuer = null;
            let delivered = meta?.delivered_amount;
            
            if (typeof tx.Amount === 'object' || (delivered && typeof delivered === 'object')) {
                 isL2 = true;
                 if (delivered && typeof delivered === 'object') {
                     amt = parseFloat(delivered.value); tokenName = delivered.currency.length > 3 ? hexToASCII(delivered.currency) : delivered.currency; issuer = delivered.issuer;
                 } else {
                     amt = parseFloat(tx.Amount.value); tokenName = tx.Amount.currency.length > 3 ? hexToASCII(tx.Amount.currency) : tx.Amount.currency; issuer = tx.Amount.issuer;
                 }
                 type = "L2"; color = "text-cyan-400"; mapColor = "#00ffff";
                 metrics.uniqueL2.add(tokenName);
            } else if (typeof tx.Amount === 'string') {
                if (delivered && typeof delivered === 'string') amt = parseInt(delivered) / 1000000; else amt = parseInt(tx.Amount) / 1000000;
            } else if (tx.TransactionType === 'OfferCreate') {
                let val = 0;
                if (typeof tx.TakerGets === 'string') val = parseInt(tx.TakerGets) / 1000000;
                else if (typeof tx.TakerPays === 'string') val = parseInt(tx.TakerPays) / 1000000;
                amt = val; 
                if (amt < 1) return;
                type = "DEX"; color = "text-purple-400"; mapColor = "#aa00ff";
            } 

            const entFrom = KNOWN_WALLETS[tx.Account]; const entTo = KNOWN_WALLETS[tx.Destination];
            let nameFrom = entFrom ? entFrom.name : null; let nameTo = entTo ? entTo.name : null;
            const isHVT = (entFrom && entFrom.type === 'HVT') || (entTo && entTo.type === 'HVT');
            const isWhale = !isL2 && amt >= 100000; 
            const isExchange = nameFrom || nameTo; 

            metrics.txCount++;
            let currentPrice = parseFloat(document.getElementById('price-display').innerText.replace('$','')) || 0; 

            if (isL2) {
                metrics.totalL2Vol += amt; 
                metrics.l2TxCount++;
                blackbox.totalL2 += amt; 
            } else {
                metrics.totalXRPVol += amt;
                metrics.totalUSDVol += (amt * currentPrice);
                if (amt < 10000) metrics.fishCount++; else if (amt < 100000) metrics.sharkCount++; else metrics.whaleCount++;
                blackbox.totalXRP += amt;
                blackbox.totalUSD += (amt * currentPrice);
                blackbox.txCount++; 
                const today = new Date().toISOString().split('T')[0];
                if (blackbox.dailySnapshots[today]) {
                    blackbox.dailySnapshots[today].xrp += amt;
                    blackbox.dailySnapshots[today].usd += (amt * currentPrice);
                    blackbox.dailySnapshots[today].tx++;
                } else {
                    blackbox.dailySnapshots[today] = { xrp: amt, usd: (amt*currentPrice), tx: 1 };
                }
            } 

            if (isSuccess && (amt >= 100000 || isHVT) && !isL2) {
                 const repTx = {
                     hash: tx.hash,
                     amt: amt,
                     wallet: nameFrom || tx.Account,
                     type: getReportType(amt, isExchange),
                     out: getOutflow(nameFrom, nameTo),
                     time: new Date().toISOString()
                 };
                 renderReportRow(repTx);
                 if (!blackbox.whaleHits) blackbox.whaleHits = [];
                 blackbox.whaleHits.unshift(repTx);
                 if (blackbox.whaleHits.length > 100) blackbox.whaleHits.pop(); 
                 saveBlackbox(); 
            }
            
            if (isHVT) { 
                saveCase({hash:tx.hash, amt:amt, from:nameFrom||tx.Account, to:nameTo||tx.Destination, type:'HVT'}); 
                /* v16.7.1: HVT intercept files to Evidence Locker only (saveCase above). Removed addHVTRow() that polluted #hvt-list watchlist. */ 
                playAlert('HVT'); 
                color = "text-yellow-300"; 

                blackbox.hvtHits.unshift({
                    date: new Date().toISOString(),
                    hash: tx.hash,
                    amt: amt,
                    desc: `${nameFrom||tx.Account} -> ${nameTo||tx.Destination}`
                });
                if(blackbox.hvtHits.length > 50) blackbox.hvtHits.pop();
            } 

            if (isWhale && isSuccess) { triggerWhaleAlert(); } 

            if(!isSuccess) { color = "text-gray-500"; mapColor = "#333333"; }
            const dispFrom = nameFrom ? `<span class="entity-name">${_htmlEsc(nameFrom)}</span>` : tx.Account ? tx.Account.substring(0,4)+'...' : '???';
            const dispTo = nameTo ? `<span class="entity-name">${_htmlEsc(nameTo)}</span>` : tx.Destination ? tx.Destination.substring(0,4)+'...' : 'DEX';
            
            let showInFeed = true;
            if (activeFilter === 'small' && (isL2 || amt >= 100000)) showInFeed = false;
            if (activeFilter === 'whale' && (isL2 || amt < 100000)) showInFeed = false;
            if (activeFilter === 'exchange' && (!isL2 && !isExchange)) showInFeed = false;
            if (activeFilter === 'l2' && !isL2) showInFeed = false; 

            if (showInFeed) {
                const feed = document.getElementById('feed');
                if (feed.innerText.includes("AWAITING")) feed.innerHTML = "";
                
                const row = document.createElement('div'); row.className = "tx-row" + (!isSuccess ? " tx-failed" : "");
                let displayAmt = isL2 ? `${amt.toLocaleString(undefined, {minimumFractionDigits:0, maximumFractionDigits:6})} ${SWE(tokenName)}` : `${amt.toLocaleString(undefined, {minimumFractionDigits:0, maximumFractionDigits:6})} XRP`;
                const flowPill = (_flow && _flow.label && !isHVT) ? `<span class="tag-pill" style="background:#001a2a;color:#66ccff;border:1px solid #045566">${SWE(_flow.label)}</span>` : '';
                row.innerHTML = `<div class="row-top ${color}"><div class="flex items-center gap-2"><span class="font-bold text-base text-shadow-lime">${displayAmt}</span>${isHVT ? '<span class="tag-pill tag-hvt">HVT</span>' : ''}${isL2 ? `<span class="tag-pill tag-l2">${SWE(tokenName)}</span>` : ''}${flowPill}${!isSuccess ? '<span class="tag-pill tag-fail">FAIL</span>' : ''}</div><div class="text-[10px] font-mono text-gray-500">${new Date().toLocaleTimeString()}</div></div><div class="flex justify-between text-[11px] font-mono text-gray-400"><span>${dispFrom} ➔ ${dispTo}</span></div><div class="btn-row"><button class="action-btn trace-btn" onclick="traceWallet('${tx.Account}')">TRACE</button><button class="action-btn" onclick="openScan('${tx.hash}')">SCAN</button><button class="action-btn" onclick='saveCase(${JSON.stringify({hash:tx.hash, amt, from:dispFrom, to:dispTo})})'>SAVE</button></div>`;
                
                feed.prepend(row);
                if(feed.children.length > 40) feed.lastChild.remove();
            } 

            if (mapActive && isSuccess) bubbles.push(new Bubble(isL2 ? tokenName : amt.toLocaleString(undefined, {maximumFractionDigits:0}), amt, mapColor, tx.hash, nameFrom||tx.Account, nameTo||tx.Destination, type, issuer));
        } 

        // --- UI FUNCTIONS ---
        function toggleAlerts() {
            alertsEnabled = !alertsEnabled;
            const btn = document.getElementById('alert-toggle');
            if(alertsEnabled) {
                btn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"></path><path d="M13.73 21a2 2 0 0 1-3.46 0"></path></svg>`;
                btn.classList.add('tac-active');
            } else {
                btn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"></path><line x1="2" y1="2" x2="22" y2="22"></line></svg>`;
                btn.classList.remove('tac-active');
            }
        } 

        function toggleSong() {
            const song = document.getElementById('app-song');
            const btn = document.getElementById('song-btn');
            if (!song) return;
            // The theme plays ONCE (no loop). This button is a real STOP/REPLAY:
            // if it's currently playing, stop it dead and rewind; otherwise
            // replay from the top. No lingering muted-but-playing state.
            const playing = !song.paused && !song.ended;
            if (playing) {
                song.pause();
                try { song.currentTime = 0; } catch(e){}
            } else {
                song.muted = false; song.volume = 0.55;
                try { song.currentTime = 0; } catch(e){}
                song.play().catch(function(){});
            }
            const nowPlaying = !song.paused;
            try { localStorage.setItem('SW_SONG_MUTED', nowPlaying ? '0' : '1'); } catch(e){}
            if (btn) btn.classList.toggle('tac-active', nowPlaying);
            try { showToast(nowPlaying ? 'THEME ON' : 'THEME STOPPED'); } catch(e){}
        }

        function toggleMute() {
            if(!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            if(audioCtx.state === 'suspended') audioCtx.resume();
            audioEnabled = !audioEnabled;
            const btn = document.getElementById('mute-btn');
            if(audioEnabled) {
                btn.innerHTML = `<svg id="icon-vol" viewBox="0 0 24 24" fill="none" stroke="currentColor"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07"></path></svg>`;
                btn.classList.add('tac-active');
                playTone(600, 0.1, "sine");
            } else {
                btn.innerHTML = `<svg id="icon-vol" viewBox="0 0 24 24" fill="none" stroke="currentColor"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><line x1="23" y1="9" x2="17" y2="15"></line><line x1="17" y1="9" x2="23" y2="15"></line></svg>`;
                btn.classList.remove('tac-active');
            }
        }
        function playTone(freq, duration, type="square") { if(!audioEnabled || !audioCtx) return; const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain(); osc.type = type; osc.frequency.setValueAtTime(freq, audioCtx.currentTime); gain.gain.setValueAtTime(0.1, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration); osc.connect(gain); gain.connect(audioCtx.destination); osc.start(); osc.stop(audioCtx.currentTime + duration); }
        function playAlert(type) { if(!alertsEnabled) return; if (type === 'HVT') { playTone(1200, 0.1); setTimeout(() => playTone(1200, 0.1), 150); setTimeout(() => playTone(1200, 0.2), 300); } else { playTone(400, 0.2, "sine"); } }
        
        function openModal(b) { 
            document.getElementById('modal-title').innerText = "INTEL: " + (b.type || 'TX');
            document.getElementById('mod-amt').innerText = typeof b.val === 'number' ? b.val.toLocaleString() + " " + (String(b.label == null ? '' : b.label).includes(' ') ? '' : 'XRP') : b.label;
            document.getElementById('mod-amt').style.color = b.color || '#00ff00'; 
            document.getElementById('mod-type').innerText = b.type || 'TX'; 
            
            if (b.nodeType === 'GRAPH_NODE') {
                document.getElementById('modal-title').innerText = "TARGET NODE";
                document.getElementById('mod-type').innerText = "WALLET ENTITY";
                document.getElementById('mod-from').innerText = b.id;
                document.getElementById('mod-to').innerText = "NET LINKED";
                document.getElementById('mod-trace-btn').innerText = "EXPAND NET";
                document.getElementById('mod-trace-btn').onclick = () => traceWallet(b.id);
                document.getElementById('mod-scan-btn').onclick = () => { closeModal(); openRiskPanel(b.id); };
                document.getElementById('mod-copy-wallet').onclick = () => copyHash(b.id);
                document.getElementById('mod-copy-hash').style.display = 'none';
                document.getElementById('mod-save-btn').style.display = 'none';
            } else {
                document.getElementById('mod-from').innerText = b.from; 
                document.getElementById('mod-to').innerText = b.to; 
                document.getElementById('mod-trace-btn').innerText = "TRACE";
                document.getElementById('mod-trace-btn').onclick = () => traceWallet(b.from); 
                document.getElementById('mod-scan-btn').onclick = () => { closeModal(); openRiskPanel(b.from); };
                document.getElementById('mod-copy-hash').style.display = 'block';
                document.getElementById('mod-copy-hash').onclick = () => copyHash(b.hash); 
                document.getElementById('mod-copy-wallet').onclick = () => copyHash(b.from); 
                document.getElementById('mod-save-btn').style.display = 'block';
                document.getElementById('mod-save-btn').onclick = () => { saveCase({hash:b.hash, amt:b.val, from:b.from, to:b.to}); closeModal(); showToast("EVIDENCE SECURED"); }; 
            }
            document.getElementById('bubble-modal').classList.add('modal-active'); 
        } 

